/** Process-wide serialized append handles for durable human-readable logging. */

import fs, { promises as fsPromises } from 'node:fs';
import path from 'node:path';
import { ensureDirectory } from '../utils/file-io.js';

export type AppendSearchScope = 'whole-file' | 'current-execution';
export type AppendMarkerMatch = 'exact-line' | 'line-suffix';

export interface AppendIfAbsentOptions {
  readonly marker: string;
  readonly scope: AppendSearchScope;
  readonly match: AppendMarkerMatch;
  readonly flush?: boolean;
}

interface SharedLogEntry {
  readonly filePath: string;
  readonly stream: fs.WriteStream;
  readonly ready: Promise<void>;
  queue: Promise<void>;
  references: number;
  closing: boolean;
}

const sharedLogs = new Map<string, SharedLogEntry>();
let warned = false;
let agentLogWarned = false;

export function warnLoggingFailure(): void {
  if (warned) return;
  warned = true;
  console.error('Shannon could not write scan progress to workflow.log.');
}

/**
 * A per-agent projection is best-effort: its failure must never disturb the canonical
 * workflow.log, so it is warned about separately and never surfaced as a workflow.log fault.
 */
export function warnAgentLoggingFailure(): void {
  if (agentLogWarned) return;
  agentLogWarned = true;
  console.error('Shannon could not write a per-agent log projection; the combined workflow.log is unaffected.');
}

/** Open the append stream and track when it is safe to write, so an early `write()` waits on `open` instead of racing it. */
function createSharedEntry(filePath: string): SharedLogEntry {
  const stream = fs.createWriteStream(filePath, { flags: 'a', encoding: 'utf8', autoClose: true });
  const ready = new Promise<void>((resolve, reject) => {
    const onOpen = (): void => {
      cleanup();
      resolve();
    };
    const onError = (): void => {
      cleanup();
      reject(new Error('workflow log stream could not be opened'));
    };
    const cleanup = (): void => {
      stream.removeListener('open', onOpen);
      stream.removeListener('error', onError);
    };
    stream.once('open', onOpen);
    stream.once('error', onError);
  });
  stream.on('error', warnLoggingFailure);
  return { filePath, stream, ready, queue: Promise.resolve(), references: 0, closing: false };
}

/**
 * Chain one more operation onto an entry's serial queue, so writes from any number of concurrent
 * `LogStream` handles to the same file still land in the order they were issued. The queue is
 * reset to a settled promise regardless of outcome, so one failed write cannot wedge every
 * write after it.
 */
function enqueue<T>(entry: SharedLogEntry, operation: () => Promise<T>): Promise<T> {
  const result = entry.queue.then(operation, operation);
  entry.queue = result.then(
    () => undefined,
    () => undefined,
  );
  return result;
}

function writeToStream(stream: fs.WriteStream, text: string): Promise<void> {
  return new Promise((resolve, reject) => {
    stream.write(text, 'utf8', (error) => {
      if (error) reject(new Error('workflow log write failed'));
      else resolve();
    });
  });
}

function syncStream(stream: fs.WriteStream): Promise<void> {
  const descriptor = (stream as fs.WriteStream & { readonly fd: number | null }).fd;
  if (descriptor === null) return Promise.resolve();
  return new Promise((resolve, reject) => {
    fs.fsync(descriptor, (error) => {
      if (error) reject(new Error('workflow log flush failed'));
      else resolve();
    });
  });
}

/**
 * Restrict a marker search to the text written since the most recent resume boundary. A resumed
 * run reopens the same log file, so without this a `current-execution` marker check would also
 * match a line written by a previous, already-finished execution.
 */
function currentExecution(content: string): string {
  const matches = [...content.matchAll(/^RESUMED\r?$/gmu)];
  const last = matches.at(-1);
  return last?.index === undefined ? content : content.slice(last.index);
}

function markerExists(content: string, options: AppendIfAbsentOptions): boolean {
  const searched = options.scope === 'current-execution' ? currentExecution(content) : content;
  const lines = searched.split(/\r?\n/u);
  if (options.match === 'exact-line') return lines.includes(options.marker);
  return lines.some((line) => line.endsWith(options.marker));
}

/** A reference-counted handle to one process-wide append stream. */
export class LogStream {
  private released = false;

  private constructor(private readonly entry: SharedLogEntry) {}

  /**
   * Take a reference on the shared entry for `filePath`, opening it if this is the first
   * reference. If a prior lease is mid-{@link release} when this call arrives, wait for that
   * drain to finish rather than reusing an entry that is about to be removed from the map;
   * the loop re-reads the map afterward because the entry may have been deleted, or replaced
   * by a new opener, while this call was waiting.
   */
  static async acquire(filePath: string): Promise<LogStream> {
    const absolutePath = path.resolve(filePath);
    await ensureDirectory(path.dirname(absolutePath));
    let entry = sharedLogs.get(absolutePath);
    while (entry?.closing === true) {
      await entry.queue;
      entry = sharedLogs.get(absolutePath);
    }
    if (entry === undefined) {
      entry = createSharedEntry(absolutePath);
      sharedLogs.set(absolutePath, entry);
    }
    entry.references += 1;
    try {
      await entry.ready;
    } catch (error) {
      entry.references -= 1;
      if (entry.references === 0) sharedLogs.delete(absolutePath);
      warnLoggingFailure();
      throw error;
    }
    return new LogStream(entry);
  }

  /** Queue an append; `flush` fsyncs before resolving, for the low-frequency structural lines that must be durable. */
  write(text: string, flush = false): Promise<void> {
    if (this.released) return Promise.reject(new Error('workflow log handle was released'));
    return enqueue(this.entry, async () => {
      await writeToStream(this.entry.stream, text);
      if (flush) await syncStream(this.entry.stream);
    });
  }

  /**
   * Append `text` only if its marker is not already present, so a structural line (a header, a
   * resume boundary) survives a Temporal activity retry without being written twice. The check
   * and the write share the same queued operation, so a concurrent writer on this entry cannot
   * observe the marker as absent and duplicate it.
   */
  appendIfAbsent(text: string, options: AppendIfAbsentOptions): Promise<boolean> {
    if (this.released) return Promise.reject(new Error('workflow log handle was released'));
    return enqueue(this.entry, async () => {
      const content = await fsPromises.readFile(this.entry.filePath, 'utf8').catch(() => '');
      if (markerExists(content, options)) return false;
      await writeToStream(this.entry.stream, text);
      if (options.flush === true) await syncStream(this.entry.stream);
      return true;
    });
  }

  /**
   * Drop this handle's reference. Only the last outstanding reference actually closes the
   * underlying file descriptor; every earlier release just decrements the count so other
   * concurrent leaseholders (an agent still mid-write, a stage still draining) are unaffected.
   * The close itself is queued behind any writes already pending on this entry, and `closing`
   * gates a new {@link acquire} until it finishes, so no writer ever sees a half-closed stream.
   */
  async release(): Promise<void> {
    if (this.released) return;
    this.released = true;
    this.entry.references -= 1;
    await enqueue(this.entry, async () => {
      if (this.entry.references > 0 || this.entry.closing) return;
      this.entry.closing = true;
      await new Promise<void>((resolve) => this.entry.stream.end(resolve));
      if (this.entry.references === 0 && sharedLogs.get(this.entry.filePath) === this.entry) {
        sharedLogs.delete(this.entry.filePath);
      }
    });
  }

  get path(): string {
    return this.entry.filePath;
  }
}

/**
 * CheckpointProvider — injectable interface for external state persistence.
 *
 * Called before and after each agent to support skip-guard (resume) and
 * post-agent artifact persistence. During the concurrent vulnerability-exploitation
 * phase, 5 pipelines run in parallel — methods fire per-agent for granular control.
 *
 * Default: no-op (skip nothing, persist nothing).
 */

import type { AgentMetrics, PipelineState } from '../temporal/shared.js';

/** Result of a pre-agent skip check. */
export interface SkipDecision {
  readonly skip: boolean;
  readonly metrics?: AgentMetrics; // Required when skip=true
}

/** File-system context passed after agent completion for artifact persistence. */
export interface CheckpointContext {
  readonly repoPath: string;
  readonly sessionId: string;
  readonly deliverablesSubdir: string;
  readonly outputPath?: string;
}

export interface CheckpointProvider {
  /**
   * Called before an agent activity executes.
   * Return { skip: true, metrics } to skip the agent (e.g., output files already exist).
   * Return { skip: false } to run normally.
   */
  shouldSkipAgent(agentName: string, repoPath: string, deliverablesSubdir: string): Promise<SkipDecision>;

  /**
   * Called after an agent activity succeeds.
   * Receives pipeline state and optional file context for artifact persistence.
   */
  onAgentComplete(agentName: string, phase: string, state: PipelineState, context?: CheckpointContext): Promise<void>;
}

/** Default no-op implementation — no external checkpointing. */
export class NoOpCheckpointProvider implements CheckpointProvider {
  async shouldSkipAgent(): Promise<SkipDecision> {
    return { skip: false };
  }

  async onAgentComplete(): Promise<void> {
    // No-op
  }
}

package openaiapi

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"go-micro.dev/v6/model"
)

// Stream opens an OpenAI-compatible chat completions SSE stream.
func Stream(ctx context.Context, opts model.Options, req *model.Request, basePath string) (model.Stream, error) {
	apiReq := Request(opts, Messages(req), nil)
	apiReq["stream"] = true
	apiReq["stream_options"] = map[string]any{"include_usage": true}
	reqBody, err := json.Marshal(apiReq)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal stream request: %w", err)
	}
	apiURL := strings.TrimRight(opts.BaseURL, "/") + basePath
	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, apiURL, bytes.NewReader(reqBody))
	if err != nil {
		return nil, fmt.Errorf("failed to create stream request: %w", err)
	}
	httpReq.Header.Set("Content-Type", "application/json")
	httpReq.Header.Set("Accept", "text/event-stream")
	httpReq.Header.Set("Authorization", "Bearer "+opts.APIKey)

	httpResp, err := http.DefaultClient.Do(httpReq)
	if err != nil {
		return nil, fmt.Errorf("stream API request failed: %w", err)
	}
	if httpResp.StatusCode != http.StatusOK {
		defer httpResp.Body.Close()
		respBody, _ := io.ReadAll(httpResp.Body)
		return nil, fmt.Errorf("stream API error (%s): %s", httpResp.Status, string(respBody))
	}
	return &StreamReader{body: httpResp.Body, scanner: bufio.NewScanner(httpResp.Body)}, nil
}

// StreamReader reads OpenAI-compatible server-sent event chunks.
type StreamReader struct {
	body       io.ReadCloser
	scanner    *bufio.Scanner
	closed     bool
	hasContent bool
}

func (s *StreamReader) Recv() (*model.Response, error) {
	for s.scanner.Scan() {
		line := strings.TrimSpace(s.scanner.Text())
		if line == "" || strings.HasPrefix(line, ":") {
			continue
		}
		if !strings.HasPrefix(line, "data:") {
			continue
		}
		data := strings.TrimSpace(strings.TrimPrefix(line, "data:"))
		if data == "[DONE]" {
			return nil, io.EOF
		}
		var chunk struct {
			Choices []struct {
				FinishReason string `json:"finish_reason"`
				Delta        struct {
					Content string `json:"content"`
				} `json:"delta"`
			} `json:"choices"`
			Usage *struct {
				PromptTokens     int `json:"prompt_tokens"`
				CompletionTokens int `json:"completion_tokens"`
				TotalTokens      int `json:"total_tokens"`
			} `json:"usage"`
		}
		if err := json.Unmarshal([]byte(data), &chunk); err != nil {
			return nil, fmt.Errorf("failed to parse stream chunk: %w", err)
		}
		response := &model.Response{}
		if len(chunk.Choices) > 0 {
			choice := chunk.Choices[0]
			if strings.TrimSpace(choice.Delta.Content) != "" {
				s.hasContent = true
			}
			if choice.FinishReason == "length" && !s.hasContent {
				return nil, model.ErrOutputLimit
			}
			response.Reply, response.StopReason = choice.Delta.Content, choice.FinishReason
		}
		if chunk.Usage != nil {
			response.Usage = model.Usage{InputTokens: chunk.Usage.PromptTokens, OutputTokens: chunk.Usage.CompletionTokens, TotalTokens: chunk.Usage.TotalTokens}
		}
		if response.Reply != "" || response.StopReason != "" || chunk.Usage != nil {
			return response, nil
		}
	}
	if err := s.scanner.Err(); err != nil {
		return nil, err
	}
	return nil, io.EOF
}

func (s *StreamReader) Close() error {
	if s.closed {
		return nil
	}
	s.closed = true
	return s.body.Close()
}

package agent

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"strings"
	"sync"

	"github.com/google/uuid"

	"go-micro.dev/v6/model"
)

// StreamEventType identifies an event emitted by a tool-aware agent stream.
type StreamEventType string

const (
	// StreamEventToolStart is emitted immediately before a tool call runs.
	StreamEventToolStart StreamEventType = "tool_start"
	// StreamEventToolEnd is emitted after a tool call returns or is refused.
	StreamEventToolEnd StreamEventType = "tool_end"
	// StreamEventToken carries a chunk of the final answer.
	StreamEventToken StreamEventType = "token"
	// StreamEventDone carries the completed agent response.
	StreamEventDone StreamEventType = "done"
)

// StreamEvent is one event from StreamAsk.
type StreamEvent struct {
	Type     StreamEventType
	Token    string
	ToolCall model.ToolCall
	Result   model.ToolResult
	Response *Response
}

// AgentStream is a stream of tool execution events followed by final-answer chunks.
type AgentStream interface {
	Recv() (*StreamEvent, error)
	Close() error
}

// StreamAsk runs an agent Ask turn with tool start/end events and streams the final answer.
// It is additive for callers that hold the public Agent interface; concrete agents also
// expose the same method directly.
func StreamAsk(ctx context.Context, ag Agent, message string) (AgentStream, error) {
	streamer, ok := ag.(interface {
		StreamAsk(context.Context, string) (AgentStream, error)
	})
	if !ok {
		return nil, errors.New("agent: StreamAsk unsupported by implementation")
	}
	return streamer.StreamAsk(ctx, message)
}

// StreamResumer is the optional capability for resuming a run as a stream.
type StreamResumer interface {
	ResumeStreamAsk(context.Context, string) (AgentStream, error)
}

func (a *agentImpl) ResumeStreamAsk(ctx context.Context, runID string) (AgentStream, error) {
	return a.resumeStreamAsk(ctx, runID)
}

// ResumeStreamAsk resumes a checkpointed agent run and emits the same event
// shape as StreamAsk. Completed runs are streamed from the persisted response;
// unfinished runs continue from their checkpoint and emit tool events for any
// work that still needs to run. Tool calls already recorded as done in the
// checkpoint are reused by the agent checkpoint wrapper and are not re-executed.
func ResumeStreamAsk(ctx context.Context, ag Agent, runID string) (AgentStream, error) {
	a, ok := ag.(StreamResumer)
	if !ok {
		return nil, errors.New("agent: ResumeStreamAsk unsupported by implementation")
	}
	return a.ResumeStreamAsk(ctx, runID)
}

// StreamAsk runs tools like Ask, emits ToolStart/ToolEnd events as they execute,
// then emits chunks of the final answer followed by a Done event.
func (a *agentImpl) StreamAsk(ctx context.Context, message string) (AgentStream, error) {
	streamCtx, cancel := context.WithCancel(ctx)
	events := make(chan *StreamEvent, 16)
	done := make(chan struct{})
	s := &agentStream{events: events, done: done, cancel: cancel}

	go func() {
		defer close(events)
		defer close(done)
		resp, err := a.askWithStreamEvents(streamCtx, message, events)
		if err != nil {
			s.setErr(err)
			return
		}
		for _, tok := range splitStreamTokens(resp.Reply) {
			if !sendStreamEvent(ctx, events, &StreamEvent{Type: StreamEventToken, Token: tok}) {
				return
			}
		}
		_ = sendStreamEvent(ctx, events, &StreamEvent{Type: StreamEventDone, Response: resp})
	}()
	return s, nil
}

func (a *agentImpl) resumeStreamAsk(ctx context.Context, runID string) (AgentStream, error) {
	streamCtx, cancel := context.WithCancel(ctx)
	events := make(chan *StreamEvent, 16)
	done := make(chan struct{})
	s := &agentStream{events: events, done: done, cancel: cancel}

	go func() {
		defer close(events)
		defer close(done)
		resp, err := a.resumeWithStreamEvents(streamCtx, runID, events)
		if err != nil {
			s.setErr(err)
			return
		}
		for _, tok := range splitStreamTokens(resp.Reply) {
			if !sendStreamEvent(ctx, events, &StreamEvent{Type: StreamEventToken, Token: tok}) {
				return
			}
		}
		_ = sendStreamEvent(ctx, events, &StreamEvent{Type: StreamEventDone, Response: resp})
	}()
	return s, nil
}

func (a *agentImpl) askWithStreamEvents(ctx context.Context, message string, events chan<- *StreamEvent) (*Response, error) {
	a.mu.Lock()
	defer a.mu.Unlock()

	if a.tools == nil {
		a.tools = model.NewTools(a.opts.Registry, model.ToolClient(a.opts.Client))
	}
	base := a.toolHandler()
	handler := func(ctx context.Context, call model.ToolCall) model.ToolResult {
		_ = sendStreamEvent(ctx, events, &StreamEvent{Type: StreamEventToolStart, ToolCall: call})
		result := base(ctx, call)
		_ = sendStreamEvent(ctx, events, &StreamEvent{Type: StreamEventToolEnd, ToolCall: call, Result: result})
		return result
	}
	a.setupWithToolHandler(handler)
	defer a.setupWithToolHandler(nil)
	return a.askLocked(ctx, uuid.New().String(), message, a.parentRunID, nil, true)
}

func (a *agentImpl) resumeWithStreamEvents(ctx context.Context, runID string, events chan<- *StreamEvent) (*Response, error) {
	if a.opts.Checkpoint == nil {
		return nil, errors.New("agent: ResumeStreamAsk requires a checkpoint")
	}
	run, ok, err := a.opts.Checkpoint.Load(ctx, runID)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, errors.New("agent: checkpointed run not found")
	}
	if run.Status == "done" {
		var resp Response
		if err := json.Unmarshal(run.State.Data, &resp); err != nil {
			return nil, err
		}
		return &resp, nil
	}
	if terminalAgentRunStatus(run.Status) {
		return nil, &TerminalRunError{RunID: run.ID, Status: run.Status, message: "agent: checkpointed run is terminal with status " + run.Status}
	}

	a.mu.Lock()
	defer a.mu.Unlock()
	if a.tools == nil {
		a.tools = model.NewTools(a.opts.Registry, model.ToolClient(a.opts.Client))
	}
	base := a.toolHandler()
	handler := func(ctx context.Context, call model.ToolCall) model.ToolResult {
		_ = sendStreamEvent(ctx, events, &StreamEvent{Type: StreamEventToolStart, ToolCall: call})
		result := base(ctx, call)
		_ = sendStreamEvent(ctx, events, &StreamEvent{Type: StreamEventToolEnd, ToolCall: call, Result: result})
		return result
	}
	a.setupWithToolHandler(handler)
	defer a.setupWithToolHandler(nil)
	if paused := pendingApproval(run); paused != nil {
		return nil, paused
	}
	if run.Status == "paused" {
		if run.State.Stage == agentInputStep {
			return nil, &AwaitingInputError{RunID: run.ID, message: "agent: checkpointed run is input-required; resume with ResumeInput"}
		}
		run.Status = "running"
		run.State.Stage = agentAskStep
	}
	return a.askLocked(ctx, run.ID, string(run.State.Data), run.ParentID, &run, false)
}

type agentStreamAdapter struct {
	stream AgentStream
}

type memoryRecordingStream struct {
	stream model.Stream
	memory Memory

	mu     sync.Mutex
	chunks []string
	closed bool
}

func (s *memoryRecordingStream) Recv() (*model.Response, error) {
	resp, err := s.stream.Recv()
	if resp != nil && resp.Reply != "" {
		s.mu.Lock()
		s.chunks = append(s.chunks, resp.Reply)
		s.mu.Unlock()
	}
	if errors.Is(err, io.EOF) {
		s.recordAssistant()
	}
	return resp, err
}

func (s *memoryRecordingStream) Close() error {
	s.recordAssistant()
	return s.stream.Close()
}

func (s *memoryRecordingStream) recordAssistant() {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return
	}
	s.closed = true
	if reply := strings.Join(s.chunks, ""); reply != "" {
		s.memory.Add("assistant", reply)
	}
}

func (s *agentStreamAdapter) Recv() (*model.Response, error) {
	for {
		event, err := s.stream.Recv()
		if err != nil {
			return nil, err
		}
		if event == nil {
			continue
		}
		switch event.Type {
		case StreamEventToken:
			if event.Token == "" {
				continue
			}
			return &model.Response{Reply: event.Token}, nil
		case StreamEventDone:
			return nil, io.EOF
		}
	}
}

func (s *agentStreamAdapter) Close() error {
	return s.stream.Close()
}

func (a *agentImpl) streamAskAI(ctx context.Context, message string) (model.Stream, error) {
	stream, err := a.StreamAsk(ctx, message)
	if err != nil {
		return nil, err
	}
	return &agentStreamAdapter{stream: stream}, nil
}

type agentStream struct {
	events <-chan *StreamEvent
	done   <-chan struct{}
	cancel context.CancelFunc
	mu     sync.Mutex
	err    error
}

func (s *agentStream) Recv() (*StreamEvent, error) {
	ev, ok := <-s.events
	if ok {
		return ev, nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.err != nil {
		return nil, s.err
	}
	return nil, io.EOF
}

func (s *agentStream) Close() error {
	if s.cancel != nil {
		s.cancel()
	}
	<-s.done
	return nil
}

func (s *agentStream) setErr(err error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.err = err
}

func sendStreamEvent(ctx context.Context, events chan<- *StreamEvent, ev *StreamEvent) bool {
	select {
	case events <- ev:
		return true
	case <-ctx.Done():
		return false
	}
}

func splitStreamTokens(reply string) []string {
	if reply == "" {
		return nil
	}
	parts := strings.Fields(reply)
	if len(parts) == 0 {
		return []string{reply}
	}
	out := make([]string, 0, len(parts))
	for i, part := range parts {
		if i > 0 {
			part = " " + part
		}
		out = append(out, part)
	}
	return out
}

"""DeerFlow LangGraph 流式响应解析工具

参考 astrbot 实现的 deerflow_stream_utils。
"""

from __future__ import annotations

import typing
from collections.abc import Iterable


def extract_text(content: typing.Any) -> str:
    """从消息 content 中提取纯文本"""
    if isinstance(content, str):
        return content
    if isinstance(content, dict):
        if isinstance(content.get('text'), str):
            return content['text']
        if 'content' in content:
            return extract_text(content.get('content'))
        if 'kwargs' in content and isinstance(content['kwargs'], dict):
            return extract_text(content['kwargs'].get('content'))
    if isinstance(content, list):
        parts: list[str] = []
        for item in content:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict):
                item_type = item.get('type')
                if item_type == 'text' and isinstance(item.get('text'), str):
                    parts.append(item['text'])
                elif 'content' in item:
                    parts.append(extract_text(item['content']))
        return '\n'.join([p for p in parts if p]).strip()
    return str(content) if content is not None else ''


def extract_messages_from_values_data(data: typing.Any) -> list[typing.Any]:
    """从 values 事件中提取 messages 列表"""
    candidates: list[typing.Any] = []
    if isinstance(data, dict):
        candidates.append(data)
        if isinstance(data.get('values'), dict):
            candidates.append(data['values'])
    elif isinstance(data, list):
        candidates.extend([x for x in data if isinstance(x, dict)])

    for item in candidates:
        messages = item.get('messages')
        if isinstance(messages, list):
            return messages
    return []


def is_ai_message(message: dict[str, typing.Any]) -> bool:
    """判断是否为 AI/assistant 消息"""
    role = str(message.get('role', '')).lower()
    if role in {'assistant', 'ai'}:
        return True

    msg_type = str(message.get('type', '')).lower()
    if msg_type in {'ai', 'assistant', 'aimessage', 'aimessagechunk'}:
        return True
    if 'ai' in msg_type and all(token not in msg_type for token in ('human', 'tool', 'system')):
        return True
    return False


def extract_latest_ai_text(messages: Iterable[typing.Any]) -> str:
    """获取最近一条 AI 消息的文本内容"""
    if isinstance(messages, (list, tuple)):
        iterable = reversed(messages)
    else:
        iterable = reversed(list(messages))

    for msg in iterable:
        if not isinstance(msg, dict):
            continue
        if is_ai_message(msg):
            text = extract_text(msg.get('content'))
            if text:
                return text
    return ''


def extract_latest_ai_message(messages: Iterable[typing.Any]) -> dict[str, typing.Any] | None:
    """获取最近一条 AI 消息对象"""
    if isinstance(messages, (list, tuple)):
        iterable = reversed(messages)
    else:
        iterable = reversed(list(messages))

    for msg in iterable:
        if not isinstance(msg, dict):
            continue
        if is_ai_message(msg):
            return msg
    return None


def is_clarification_tool_message(message: dict[str, typing.Any]) -> bool:
    """判断是否为澄清问题工具消息"""
    msg_type = str(message.get('type', '')).lower()
    tool_name = str(message.get('name', '')).lower()
    return msg_type == 'tool' and tool_name == 'ask_clarification'


def extract_latest_clarification_text(messages: Iterable[typing.Any]) -> str:
    """提取最近的澄清问题文本"""
    if isinstance(messages, (list, tuple)):
        iterable = reversed(messages)
    else:
        iterable = reversed(list(messages))

    for msg in iterable:
        if not isinstance(msg, dict):
            continue
        if is_clarification_tool_message(msg):
            text = extract_text(msg.get('content'))
            if text:
                return text
    return ''


def get_message_id(message: typing.Any) -> str:
    """提取消息 ID"""
    if not isinstance(message, dict):
        return ''
    msg_id = message.get('id')
    return msg_id if isinstance(msg_id, str) else ''


def extract_event_message_obj(data: typing.Any) -> dict[str, typing.Any] | None:
    """从事件 data 中提取消息对象"""
    msg_obj = data
    if isinstance(data, (list, tuple)) and data:
        msg_obj = data[0]
    if isinstance(msg_obj, dict) and isinstance(msg_obj.get('data'), dict):
        msg_obj = msg_obj['data']
    return msg_obj if isinstance(msg_obj, dict) else None


def extract_ai_delta_from_event_data(data: typing.Any) -> str:
    """从 messages-tuple 事件中提取 AI delta 文本"""
    msg_obj = extract_event_message_obj(data)
    if not msg_obj:
        return ''
    if is_ai_message(msg_obj):
        return extract_text(msg_obj.get('content'))
    return ''


def extract_clarification_from_event_data(data: typing.Any) -> str:
    """从事件中提取澄清问题"""
    msg_obj = extract_event_message_obj(data)
    if not msg_obj:
        return ''
    if is_clarification_tool_message(msg_obj):
        return extract_text(msg_obj.get('content'))
    return ''


def _iter_custom_event_items(data: typing.Any) -> list[dict[str, typing.Any]]:
    items: list[dict[str, typing.Any]] = []
    if isinstance(data, dict):
        return [data]
    if isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                items.append(item)
            elif isinstance(item, (list, tuple)):
                for nested in item:
                    if isinstance(nested, dict):
                        items.append(nested)
    return items


def extract_task_failures_from_custom_event(data: typing.Any) -> list[str]:
    """从 custom 事件中提取子任务失败信息"""
    failures: list[str] = []
    for item in _iter_custom_event_items(data):
        event_type = str(item.get('type', '')).lower()
        if event_type not in {'task_failed', 'task_timed_out'}:
            continue

        task_id = str(item.get('task_id', '')).strip()
        error_text = extract_text(item.get('error')).strip()
        if task_id and error_text:
            failures.append(f'{task_id}: {error_text}')
        elif error_text:
            failures.append(error_text)
        elif task_id:
            failures.append(f'{task_id}: unknown error')
        else:
            failures.append('unknown task failure')
    return failures


def build_task_failure_summary(failures: list[str]) -> str:
    """构建任务失败摘要"""
    if not failures:
        return ''
    deduped: list[str] = []
    seen: set[str] = set()
    for failure in failures:
        if failure not in seen:
            seen.add(failure)
            deduped.append(failure)
    if len(deduped) == 1:
        return f'DeerFlow subtask failed: {deduped[0]}'
    joined = '\n'.join([f'- {item}' for item in deduped[:5]])
    return f'DeerFlow subtasks failed:\n{joined}'

"""ohmo gateway-scoped provider and model commands."""

from __future__ import annotations

from pathlib import Path

from openharness.auth.manager import AuthManager
from openharness.config import load_settings

from ohmo.gateway.config import load_gateway_config, save_gateway_config


def handle_gateway_provider_command(args: str, *, workspace: str | Path | None) -> tuple[str, bool]:
    """Handle ``/provider`` against the ohmo gateway config."""
    tokens = args.split()
    statuses = AuthManager(load_settings()).get_profile_statuses()
    config = load_gateway_config(workspace)
    active = config.provider_profile
    if not tokens or tokens[0] == "show":
        info = statuses.get(active)
        if info is None:
            return f"ohmo gateway provider_profile: {active}\nStatus: unknown profile", False
        return (
            f"ohmo gateway provider_profile: {active}\n"
            f"Label: {info['label']}\n"
            f"Configured: {'yes' if info['configured'] else 'no'}\n"
            f"Base URL: {info['base_url'] or '(default)'}\n"
            f"Model: {info['model']}",
            False,
        )
    if tokens[0] == "list":
        lines = ["ohmo gateway provider profiles:"]
        for name, info in statuses.items():
            marker = "*" if name == active else " "
            configured = "ready" if info["configured"] else "missing auth"
            lines.append(f"{marker} {name} [{configured}] {info['label']} -> {info['model']}")
        return "\n".join(lines), False
    target = tokens[1] if tokens[0] == "use" and len(tokens) == 2 else (tokens[0] if len(tokens) == 1 else None)
    if target is None:
        return "Usage: /provider [show|list|PROFILE]", False
    if target not in statuses:
        return f"Unknown provider profile: {target}", False
    if target == active:
        return f"ohmo gateway already uses provider_profile={target}.", False
    save_gateway_config(config.model_copy(update={"provider_profile": target}), workspace)
    info = statuses[target]
    configured = "ready" if info["configured"] else "missing auth"
    return (
        f"ohmo gateway provider_profile set to {target} ({info['label']}, {configured}).\n"
        "Refreshing the current ohmo runtime to apply it.",
        True,
    )


def handle_gateway_model_command(args: str, *, workspace: str | Path | None) -> tuple[str, bool]:
    """Handle ``/model`` against the profile selected by ohmo gateway."""
    settings = load_settings()
    manager = AuthManager(settings)
    config = load_gateway_config(workspace)
    profile_name = config.provider_profile
    profiles = manager.list_profiles()
    profile = profiles.get(profile_name)
    if profile is None:
        return f"ohmo gateway provider_profile is unknown: {profile_name}", False

    tokens = args.split(maxsplit=1)
    if not tokens or tokens[0] == "show":
        return _format_model_status(profile_name, profile), False
    if tokens[0] == "list":
        if profile.allowed_models:
            return (
                f"Switchable models for ohmo gateway profile '{profile_name}':\n"
                + "\n".join(f"- {model}" for model in profile.allowed_models)
            ), False
        return (
            f"Profile '{profile_name}' has no pinned model list. "
            "Any model value is accepted. Use /model add MODEL to pin one."
        ), False
    if tokens[0] == "add" and len(tokens) == 2:
        model_name = tokens[1].strip()
        if not model_name:
            return "Usage: /model add MODEL", False
        manager.update_profile(profile_name, allowed_models=_dedupe([*_seed_models(profile), model_name]))
        return f"Added model '{model_name}' to ohmo gateway profile '{profile_name}'.", False
    if tokens[0] == "add":
        return "Usage: /model add MODEL", False
    if tokens[0] in {"remove", "rm"} and len(tokens) == 2:
        model_name = tokens[1].strip()
        models = [model for model in _dedupe(profile.allowed_models) if model != model_name]
        if len(models) == len(_dedupe(profile.allowed_models)):
            return f"Model '{model_name}' is not pinned for ohmo gateway profile '{profile_name}'.", False
        reset_current = (profile.last_model or "").strip() == model_name
        manager.update_profile(profile_name, allowed_models=models, last_model="" if reset_current else None)
        return f"Removed model '{model_name}' from ohmo gateway profile '{profile_name}'.", True
    if tokens[0] in {"remove", "rm"}:
        return "Usage: /model remove MODEL", False
    if tokens[0] == "clear":
        manager.update_profile(profile_name, allowed_models=[])
        return f"Cleared pinned models for ohmo gateway profile '{profile_name}'.", False
    model_name = tokens[1].strip() if tokens[0] == "set" and len(tokens) == 2 else args.strip()
    if not model_name:
        return "Usage: /model [show|list|add MODEL|remove MODEL|clear|MODEL]", False
    if profile.allowed_models and model_name.lower() != "default" and model_name not in profile.allowed_models:
        allowed = ", ".join(profile.allowed_models)
        return f"Model '{model_name}' is not allowed for ohmo gateway profile '{profile_name}'. Allowed models: {allowed}", False
    if model_name.lower() == "default":
        manager.update_profile(profile_name, last_model="")
        return f"ohmo gateway model reset to default for profile '{profile_name}'. Refreshing runtime to apply it.", True
    manager.update_profile(profile_name, last_model=model_name)
    return f"ohmo gateway model set to {model_name} for profile '{profile_name}'. Refreshing runtime to apply it.", True


def _format_model_status(profile_name, profile) -> str:
    lines = [
        f"ohmo gateway model: {profile.resolved_model}",
        f"Profile: {profile_name}",
    ]
    if profile.allowed_models:
        lines.append("Available models:")
        lines.extend(f"- {model}" for model in profile.allowed_models)
    else:
        lines.append("Available models: unrestricted for this profile")
        lines.append("Use /model add MODEL to pin switchable models.")
    return "\n".join(lines)


def _dedupe(values) -> list[str]:
    seen: set[str] = set()
    result: list[str] = []
    for value in values:
        model = str(value).strip()
        if model and model not in seen:
            result.append(model)
            seen.add(model)
    return result


def _seed_models(profile) -> list[str]:
    return _dedupe([*profile.allowed_models, profile.resolved_model])

"""OpenAI-compatible API client for providers like Alibaba DashScope, GitHub Models, etc."""

from __future__ import annotations

import asyncio
import json
import logging
import os
import re
from typing import Any, AsyncIterator
from urllib.parse import urlsplit, urlunsplit

from openai import AsyncOpenAI

from openharness.api.client import (
    ApiMessageCompleteEvent,
    ApiMessageRequest,
    ApiRetryEvent,
    ApiStreamEvent,
    ApiTextDeltaEvent,
)
from openharness.api.errors import (
    AuthenticationFailure,
    OpenHarnessApiError,
    RateLimitFailure,
    RequestFailure,
)
from openharness.api.usage import UsageSnapshot
from openharness.engine.messages import (
    ConversationMessage,
    ContentBlock,
    ImageBlock,
    TextBlock,
    ToolResultBlock,
    ToolUseBlock,
)

log = logging.getLogger(__name__)

MAX_RETRIES = 3
BASE_DELAY = 1.0
MAX_DELAY = 30.0
_MAX_COMPLETION_TOKEN_MODEL_PREFIXES = ("gpt-5", "o1", "o3", "o4")


def _token_limit_param_for_model(model: str, max_tokens: int) -> dict[str, int]:
    """Return the correct token limit field for the target OpenAI model.

    GPT-5 and the current reasoning-model families reject ``max_tokens`` and
    require ``max_completion_tokens`` instead.
    """
    normalized = model.strip().lower()
    if "/" in normalized:
        normalized = normalized.rsplit("/", 1)[-1]
    if normalized.startswith(_MAX_COMPLETION_TOKEN_MODEL_PREFIXES):
        return {"max_completion_tokens": max_tokens}
    return {"max_tokens": max_tokens}


def _convert_tools_to_openai(tools: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Convert Anthropic tool schemas to OpenAI function-calling format.

    Anthropic format:
        {"name": "...", "description": "...", "input_schema": {...}}
    OpenAI format:
        {"type": "function", "function": {"name": "...", "description": "...", "parameters": {...}}}
    """
    result = []
    for tool in tools:
        result.append({
            "type": "function",
            "function": {
                "name": tool["name"],
                "description": tool.get("description", ""),
                "parameters": tool.get("input_schema", {}),
            },
        })
    return result


def _convert_messages_to_openai(
    messages: list[ConversationMessage],
    system_prompt: str | None,
) -> list[dict[str, Any]]:
    """Convert Anthropic-style messages to OpenAI chat format.

    Key differences:
    - Anthropic: system prompt is a separate parameter
    - OpenAI: system prompt is a message with role="system"
    - Anthropic: tool_use / tool_result are content blocks
    - OpenAI: tool_calls on assistant message, tool results are separate messages
    """
    openai_messages: list[dict[str, Any]] = []

    if system_prompt:
        openai_messages.append({"role": "system", "content": system_prompt})

    for msg in messages:
        if msg.role == "assistant":
            openai_msg = _convert_assistant_message(msg)
            openai_messages.append(openai_msg)
        elif msg.role == "user":
            # User messages may contain text or tool_result blocks
            tool_results = [b for b in msg.content if isinstance(b, ToolResultBlock)]
            user_blocks = [b for b in msg.content if isinstance(b, (TextBlock, ImageBlock))]

            if tool_results:
                # Each tool result becomes a separate message with role="tool"
                for tr in tool_results:
                    openai_messages.append({
                        "role": "tool",
                        "tool_call_id": tr.tool_use_id,
                        "content": tr.content,
                    })
            if user_blocks:
                content = _convert_user_content_to_openai(user_blocks)
                if isinstance(content, str):
                    if content.strip():
                        openai_messages.append({"role": "user", "content": content})
                elif content:
                    openai_messages.append({"role": "user", "content": content})
            if not tool_results and not user_blocks:
                # Empty user message (shouldn't happen, but handle gracefully)
                openai_messages.append({"role": "user", "content": ""})

    return openai_messages


def _convert_user_content_to_openai(blocks: list[ContentBlock]) -> str | list[dict[str, Any]]:
    """Convert user text/image blocks into OpenAI chat content."""
    has_image = any(isinstance(block, ImageBlock) for block in blocks)
    if not has_image:
        return "".join(block.text for block in blocks if isinstance(block, TextBlock))

    content: list[dict[str, Any]] = []
    for block in blocks:
        if isinstance(block, TextBlock) and block.text:
            content.append({"type": "text", "text": block.text})
        elif isinstance(block, ImageBlock):
            content.append({
                "type": "image_url",
                "image_url": {
                    "url": f"data:{block.media_type};base64,{block.data}",
                },
            })
    return content


_EMPTY_REASONING_ENV = "OPENHARNESS_REQUIRE_EMPTY_REASONING_CONTENT"


def _empty_reasoning_required() -> bool:
    """True when the operator's provider requires an empty
    ``reasoning_content`` field on tool-using assistant messages
    (Kimi-on-Anthropic style). Default off — strict-OpenAI providers
    reject the field outright.
    """
    raw = os.environ.get(_EMPTY_REASONING_ENV, "").strip().lower()
    return raw in {"1", "true", "yes", "on"}


def _convert_assistant_message(msg: ConversationMessage) -> dict[str, Any]:
    """Convert an assistant ConversationMessage to OpenAI format.

    ``reasoning_content`` is a non-standard field used by thinking models
    (e.g. Kimi k2.5) to carry the model's internal chain-of-thought across
    turns. Some thinking-model providers require it on every assistant
    message with tool calls — even when empty — or they reject the request.
    Other OpenAI-compatible providers (Cerebras, OpenAI's own
    endpoint, etc.) reject the field outright with a 400
    ``wrong_api_format`` error.

    Behaviour:

    - When the streaming parser captured non-empty reasoning on
      ``msg._reasoning``, we always replay it. Models that emit reasoning
      tokens are by definition thinking models that round-trip them.
    - When there is no captured reasoning but the message has tool calls,
      we emit ``reasoning_content: ""`` only if the operator opts in via
      ``OPENHARNESS_REQUIRE_EMPTY_REASONING_CONTENT=1``. The default is
      omit, which matches strict-OpenAI providers.

    The opt-in default keeps strict-OpenAI providers (Cerebras, NVIDIA NIM,
    OpenAI direct, etc.) working out-of-the-box; Kimi-on-Anthropic users
    set the env var in their dotfiles or settings.
    """
    text_parts = [b.text for b in msg.content if isinstance(b, TextBlock)]
    tool_uses = [b for b in msg.content if isinstance(b, ToolUseBlock)]

    openai_msg: dict[str, Any] = {"role": "assistant"}

    content = "".join(text_parts)
    openai_msg["content"] = content if content else None

    # Replay reasoning_content for thinking models (stored by streaming parser)
    reasoning = getattr(msg, "_reasoning", None)
    if reasoning:
        openai_msg["reasoning_content"] = reasoning
    elif tool_uses and _empty_reasoning_required():
        # Kimi-style providers reject tool_use messages without this field
        # even when there's nothing to put in it. Opt-in via env var.
        openai_msg["reasoning_content"] = ""

    if tool_uses:
        openai_msg["tool_calls"] = [
            {
                "id": tu.id,
                "type": "function",
                "function": {
                    "name": tu.name,
                    "arguments": json.dumps(tu.input),
                },
            }
            for tu in tool_uses
        ]

    return openai_msg


def _parse_assistant_response(response: Any) -> ConversationMessage:
    """Parse an OpenAI ChatCompletion response into a ConversationMessage."""
    choice = response.choices[0]
    message = choice.message
    content: list[ContentBlock] = []

    if message.content:
        content.append(TextBlock(text=message.content))

    if message.tool_calls:
        for tc in message.tool_calls:
            try:
                args = json.loads(tc.function.arguments)
            except (json.JSONDecodeError, TypeError):
                args = {}
            content.append(ToolUseBlock(
                id=tc.id,
                name=tc.function.name,
                input=args,
            ))

    return ConversationMessage(role="assistant", content=content)


def _normalize_openai_base_url(base_url: str | None) -> str | None:
    """Normalize custom OpenAI-compatible base URLs without dropping API path segments."""
    if not base_url:
        return None
    trimmed = base_url.strip()
    if not trimmed:
        return None
    parts = urlsplit(trimmed)
    if not parts.scheme or not parts.netloc:
        return trimmed.rstrip("/")
    path = parts.path.rstrip("/")
    if not path:
        path = "/v1"
    return urlunsplit((parts.scheme, parts.netloc, path, parts.query, parts.fragment))


class OpenAICompatibleClient:
    """Client for OpenAI-compatible APIs (DashScope, GitHub Models, etc.).

    Implements the same SupportsStreamingMessages protocol as AnthropicApiClient
    so it can be used as a drop-in replacement in the agent loop.
    """

    def __init__(self, api_key: str, *, base_url: str | None = None, timeout: float | None = None) -> None:
        kwargs: dict[str, Any] = {
            "api_key": api_key,
            "default_headers": {"Authorization": f"Bearer {api_key}"},
        }
        normalized_base_url = _normalize_openai_base_url(base_url)
        if normalized_base_url:
            kwargs["base_url"] = normalized_base_url
        if timeout is not None:
            kwargs["timeout"] = timeout
        self._client = AsyncOpenAI(**kwargs)

    async def close(self) -> None:
        """Close the underlying HTTP client."""
        await self._client.close()

    async def stream_message(self, request: ApiMessageRequest) -> AsyncIterator[ApiStreamEvent]:
        """Yield text deltas and the final message, matching the Anthropic client interface."""
        last_error: Exception | None = None

        for attempt in range(MAX_RETRIES + 1):
            try:
                async for event in self._stream_once(request):
                    yield event
                return
            except OpenHarnessApiError:
                raise
            except Exception as exc:
                last_error = exc
                if attempt >= MAX_RETRIES or not self._is_retryable(exc):
                    raise self._translate_error(exc) from exc

                delay = min(BASE_DELAY * (2 ** attempt), MAX_DELAY)
                log.warning(
                    "OpenAI API request failed (attempt %d/%d), retrying in %.1fs: %s",
                    attempt + 1, MAX_RETRIES + 1, delay, exc,
                )
                yield ApiRetryEvent(
                    message=str(exc),
                    attempt=attempt + 1,
                    max_attempts=MAX_RETRIES + 1,
                    delay_seconds=delay,
                )
                await asyncio.sleep(delay)

        if last_error is not None:
            raise self._translate_error(last_error) from last_error

    async def _stream_once(self, request: ApiMessageRequest) -> AsyncIterator[ApiStreamEvent]:
        """Single attempt: stream an OpenAI chat completion."""
        openai_messages = _convert_messages_to_openai(request.messages, request.system_prompt)
        openai_tools = _convert_tools_to_openai(request.tools) if request.tools else None

        params: dict[str, Any] = {
            "model": request.model,
            "messages": openai_messages,
            "stream": True,
            "stream_options": {"include_usage": True},
        }
        params.update(_token_limit_param_for_model(request.model, request.max_tokens))
        if openai_tools:
            params["tools"] = openai_tools
            # Some providers (Kimi) error on empty reasoning_content in
            # tool-call follow-ups.  Omit the entire stream_options key if
            # tools are present – avoids triggering model-side thinking mode
            # that requires reasoning_content on every assistant message.
            params.pop("stream_options", None)

        # Collect full response while streaming text deltas
        collected_content = ""
        collected_reasoning = ""
        collected_tool_calls: dict[int, dict[str, Any]] = {}
        finish_reason: str | None = None
        usage_data: dict[str, int] = {}
        # Buffer to strip inline <think>…</think> blocks across streaming chunks.
        _think_buf = ""

        stream = await self._client.chat.completions.create(**params)
        async for chunk in stream:
            if not chunk.choices:
                # Usage-only chunk (some providers send this at the end)
                if chunk.usage:
                    usage_data = {
                        "input_tokens": chunk.usage.prompt_tokens or 0,
                        "output_tokens": chunk.usage.completion_tokens or 0,
                    }
                continue

            delta = chunk.choices[0].delta
            chunk_finish = chunk.choices[0].finish_reason

            if chunk_finish:
                finish_reason = chunk_finish

            # Accumulate reasoning_content from thinking models (not shown to user)
            reasoning_piece = getattr(delta, "reasoning_content", None) or ""
            if reasoning_piece:
                collected_reasoning += reasoning_piece

            # Stream text content to user, stripping inline <think> blocks
            if delta.content:
                _think_buf += delta.content
                visible, _think_buf = _strip_think_blocks(_think_buf)
                if visible:
                    collected_content += visible
                    yield ApiTextDeltaEvent(text=visible)

            # Accumulate tool calls
            if delta.tool_calls:
                for tc_delta in delta.tool_calls:
                    idx = tc_delta.index
                    if idx not in collected_tool_calls:
                        collected_tool_calls[idx] = {
                            "id": tc_delta.id or "",
                            "name": "",
                            "arguments": "",
                        }
                    entry = collected_tool_calls[idx]
                    if tc_delta.id:
                        entry["id"] = tc_delta.id
                    if tc_delta.function:
                        if tc_delta.function.name:
                            entry["name"] = tc_delta.function.name
                        if tc_delta.function.arguments:
                            entry["arguments"] += tc_delta.function.arguments

            # Usage in chunk (if provider sends it)
            if chunk.usage:
                usage_data = {
                    "input_tokens": chunk.usage.prompt_tokens or 0,
                    "output_tokens": chunk.usage.completion_tokens or 0,
                }

        # Build the final ConversationMessage
        content: list[ContentBlock] = []
        if collected_content:
            content.append(TextBlock(text=collected_content))

        for _idx in sorted(collected_tool_calls.keys()):
            tc = collected_tool_calls[_idx]
            # Skip phantom/empty tool calls that some providers send
            if not tc["name"]:
                continue
            try:
                args = json.loads(tc["arguments"])
            except (json.JSONDecodeError, TypeError):
                args = {}
            content.append(ToolUseBlock(
                id=tc["id"],
                name=tc["name"],
                input=args,
            ))

        final_message = ConversationMessage(role="assistant", content=content)

        # Stash reasoning for thinking models so _convert_assistant_message
        # can replay it when the message is sent back to the API
        if collected_reasoning:
            final_message._reasoning = collected_reasoning  # type: ignore[attr-defined]

        yield ApiMessageCompleteEvent(
            message=final_message,
            usage=UsageSnapshot(
                input_tokens=usage_data.get("input_tokens", 0),
                output_tokens=usage_data.get("output_tokens", 0),
            ),
            stop_reason=finish_reason,
        )

    @staticmethod
    def _is_retryable(exc: Exception) -> bool:
        status = getattr(exc, "status_code", None)
        if status and status in {429, 500, 502, 503}:
            return True
        if isinstance(exc, (ConnectionError, TimeoutError, OSError)):
            return True
        return False

    @staticmethod
    def _translate_error(exc: Exception) -> OpenHarnessApiError:
        status = getattr(exc, "status_code", None)
        msg = str(exc)
        if status == 401 or status == 403:
            return AuthenticationFailure(msg)
        if status == 429:
            return RateLimitFailure(msg)
        return RequestFailure(msg)


# Matches complete <think>…</think> blocks (DOTALL so newlines are included).
_THINK_RE = re.compile(r"<think>.*?</think>", re.DOTALL)
_THINK_OPEN_TAG = "<think>"


def _strip_think_blocks(buf: str) -> tuple[str, str]:
    """Strip complete ``<think>…</think>`` blocks and return ``(visible_text, leftover)``.

    Complete pairs are removed via regex.  An unclosed ``<think>`` is held in
    *leftover* so it can be re-evaluated once the closing tag arrives in the
    next streaming chunk.
    """
    # Remove fully-closed blocks.
    cleaned = _THINK_RE.sub("", buf)

    # Hold back any unclosed <think> for the next chunk.
    open_idx = cleaned.find(_THINK_OPEN_TAG)
    if open_idx != -1:
        return cleaned[:open_idx], cleaned[open_idx:]

    # Streaming providers may split the opening tag itself across chunk
    # boundaries (e.g. ``"<thi"`` then ``"nk>..."``). Hold back the longest
    # suffix that could still become ``<think>`` on the next chunk.
    max_prefix = min(len(cleaned), len(_THINK_OPEN_TAG) - 1)
    for prefix_len in range(max_prefix, 0, -1):
        if _THINK_OPEN_TAG.startswith(cleaned[-prefix_len:]):
            return cleaned[:-prefix_len], cleaned[-prefix_len:]

    return cleaned, ""
